use serde::Serialize;use std::{fs,path::{Path,PathBuf},process::Command};#[derive(Serialize)]struct ImageInfo{path:String,name:String}fn supported_image(path:&Path)->bool{let n=path.file_name().and_then(|v|v.to_str()).unwrap_or_default().to_ascii_lowercase();n.ends_with(".img")||n.ends_with(".img.bz2")||n.ends_with(".img.gz")||n.ends_with(".img.xz")}#[tauri::command]fn validate_image(path:String)->Result<ImageInfo,String>{let p=PathBuf::from(path);if !p.is_file(){return Err("The selected path is not a file.".into())}if !supported_image(&p){return Err("Select a SteamOS recovery image (.img, .img.bz2, .img.gz, or .img.xz).".into())}let c=fs::canonicalize(&p).map_err(|e|format!("Could not resolve the selected image: {e}"))?;let name=c.file_name().and_then(|v|v.to_str()).ok_or("Invalid image name")?.to_string();Ok(ImageInfo{path:c.to_string_lossy().into_owned(),name})}#[tauri::command]fn prototype_build(path:String)->Result<String,String>{let input=PathBuf::from(path);if !input.is_file()||!supported_image(&input){return Err("The selected SteamOS image is no longer available or supported.".into())}let parent=input.parent().ok_or("Could not determine input folder")?;let output=parent.join("SteamOS-NVIDIA-PROTOTYPE.txt");fs::write(&output,format!("SteamOS NVIDIA Image Builder prototype\n\nInput image:\n{}\n\nThis is not a bootable image.\n",input.display())).map_err(|e|format!("Could not create prototype output: {e}"))?;#[cfg(target_os="macos")]{Command::new("open").arg("-R").arg(&output).spawn().map_err(|e|format!("Created output but Finder reveal failed: {e}"))?;}Ok(output.to_string_lossy().into_owned())}#[cfg_attr(mobile,tauri::mobile_entry_point)]pub fn run(){tauri::Builder::default().plugin(tauri_plugin_dialog::init()).plugin(tauri_plugin_opener::init()).invoke_handler(tauri::generate_handler![validate_image,prototype_build]).run(tauri::generate_context!()).expect("error while running SteamOS NVIDIA Image Builder");}
